// CompositeStepTarget Something a composite's step can run (ADR-0022).
type CompositeStepTarget struct {
	// AwxId An AWX template's ID in AWX (a job template's or a workflow
	// template's: they are numbered apart). A step writes it as
	// `awx.template_id`, beside the name: it is then launched by ID,
	// whatever the template is called since (ADR-0016).
	//
	//
	// Examples: 47
	AwxId *int `json:"awx_id,omitempty"`

	// AwxWorkflow An AWX workflow template, named `awx.job_template` with `awx.workflow` true.
	AwxWorkflow *bool `json:"awx_workflow,omitempty"`

	// Inputs What `with` binds, in its form's order; read-only fields left out.
	Inputs   []CompositeStepInput `json:"inputs"`
	ItemType *CatalogItemType     `json:"item_type,omitempty"`

	// Kind How a step names it: `item` (another item, by slug), `awx`
	// (`awx.job_template`, a template's name) or `workflow` (a custom
	// workflow registered for composite steps, by key).
	Kind CompositeStepTargetKind `json:"kind"`

	// OpenOutputs Its outputs are whatever it returns (a custom workflow's result): fields not listed may be read too.
	OpenOutputs bool `json:"open_outputs"`

	// Outputs What later steps read as `steps.<key>.<name>`.
	Outputs []CompositeStepOutput `json:"outputs"`

	// Planned It builds VMs, planned with the request when it is submitted: its
	// inputs come from the form only, not from earlier steps, and it
	// has no condition or undo.
	Planned bool `json:"planned"`

	// ProjectIds The projects it is offered to, when not every project: a custom
	// workflow registered for some projects, or a workflow item whose
	// workflow is. A request of the composite from another project is
	// refused. Absent when every project may use it.
	ProjectIds *[]string `json:"project_ids,omitempty"`

	// Ref The name a step gives it, under `kind`. A job template and a
	// workflow template may have the same name: `awx_workflow` (and
	// `awx_id`) tell them apart.
	//
	//
	// Examples: db-user
	Ref string `json:"ref"`

	// Runs What it runs, which says its outputs and whether it is planned.
	Runs    CompositeStepTargetRuns `json:"runs"`
	Summary *string                 `json:"summary,omitempty"`

	// Title Examples: Create database user
	Title string `json:"title"`
}

// CompositeStepTargetKind How a step names it: `item` (another item, by slug), `awx`
